 await page.getByRole('button',{name:'Back to applications',exact:true}).click();await page.getByRole('link',{name:'Applicant app-2',exact:true}).waitFor();assert.equal(await page.getByRole('link',{name:'Applicant app-1',exact:true}).count(),0);await page.getByLabel('Show applicants',{exact:true}).selectOption('stage:Rejected');await page.getByRole('link',{name:'Applicant app-1',exact:true}).click();await page.getByRole('heading',{name:'Applicant app-1',exact:true}).waitFor();assert.equal(await page.getByRole('button',{name:'Reject',exact:true}).count(),0);mkdirSync('/tmp/reject-review-audit',{recursive:true});await page.screenshot({path:`/tmp/reject-review-audit/rejected-${width}.png`});
