 const{page}=await setup(t,{width,pdfPages:20});await page.getByRole('link',{name:'Applicant app-1',exact:true}).click();const stage=page.getByRole('region',{name:'Scrollable résumé pages',exact:true});await stage.waitFor();await stage.scrollIntoViewIfNeeded();await page.locator('canvas[data-rendered="true"]').first().waitFor();
