 await stage.evaluate(el=>el.scrollTop=el.scrollHeight*.45);await page.waitForFunction(()=>!document.querySelector('.hub-pdf-page:first-child canvas'));await page.locator('canvas[data-rendered="true"]').first().waitFor();assert.ok(await stage.locator('canvas').count()<6);
 const before=await stage.evaluate(el=>({fraction:(el.scrollTop+el.clientHeight/2)/el.scrollHeight,outer:scrollY}));await stage.evaluate(el=>{const b=el.getBoundingClientRect();el.dispatchEvent(new WheelEvent('wheel',{ctrlKey:true,deltaY:-30,clientX:b.x+b.width/2,clientY:b.y+b.height/2,bubbles:true,cancelable:true}));});await page.getByLabel('Résumé zoom',{exact:true}).filter({hasText:'127%'}).waitFor();const after=await stage.evaluate(el=>({fraction:(el.scrollTop+el.clientHeight/2)/el.scrollHeight,outer:scrollY}));assert.ok(Math.abs(after.fraction-before.fraction)<.02,JSON.stringify({before,after}));assert.ok(Math.abs(after.outer-before.outer)<2);
 await stage.evaluate(el=>{el.dispatchEvent(new Event('gesturestart',{cancelable:true}));const e=new Event('gesturechange',{cancelable:true});Object.defineProperty(e,'scale',{value:1.2});el.dispatchEvent(e);});await page.getByLabel('Résumé zoom',{exact:true}).filter({hasText:'153%'}).waitFor();
