test('applicant links preserve filter context and native modified-click behavior',async t=>{
 const{page,writes}=await setup(t);const applicant=page.getByRole('link',{name:'Applicant app-1',exact:true});const href=await applicant.getAttribute('href');const target=new URL(href,page.url());assert.equal(target.searchParams.get('application'),'app-1');for(const key of ['jobId','qualification','appliedFrom','appliedTo','timeZone'])assert.equal(target.searchParams.get(key),new URL(page.url()).searchParams.get(key));
 const before=page.url();for(const modifiers of [{metaKey:true},{ctrlKey:true},{shiftKey:true},{altKey:true},{button:1}]){
  const intercepted=await applicant.evaluate((el,mods)=>{let prevented;const observer=event=>{prevented=event.defaultPrevented;event.preventDefault();};document.addEventListener('click',observer,{once:true});el.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,...mods}));return prevented;},modifiers);assert.equal(intercepted,false,JSON.stringify(modifiers));assert.equal(page.url(),before);
 }
 const popupPromise=page.context().waitForEvent('page');await applicant.click({button:'middle'});const popup=await popupPromise;await popup.waitForURL(url=>url.searchParams.get('application')==='app-1');assert.equal(new URL(popup.url()).searchParams.get('qualification'),'pass');await popup.close();assert.equal(page.url(),before);assert.equal(writes.length,0);
 await applicant.click();await page.getByRole('heading',{name:'Applicant app-1',exact:true}).waitFor();assert.equal(new URL(page.url()).searchParams.get('application'),'app-1');
});

