 await messages.getByRole('button',{name:'Write email',exact:true}).click();await page.getByLabel('Subject',{exact:true}).fill('Synthetic follow-up');await page.getByLabel('Email body',{exact:true}).fill('Unsent draft');assert.equal(await messages.getByRole('button',{name:'Write email',exact:true}).isDisabled(),true);await page.getByRole('button',{name:'Next applicant',exact:true}).click();await page.getByRole('alertdialog').waitFor();await page.getByRole('button',{name:'Keep editing',exact:true}).click();assert.equal(await page.getByLabel('Email body',{exact:true}).inputValue(),'Unsent draft');assert.ok(writes.every(path=>path.endsWith('/viewed')));
